thinker-with-files-gemini.handleSteps:
function* ({ params }) {
    const filePaths = params?.filePaths;
    if (filePaths && filePaths.length > 0)
      yield {
        toolName: "read_files",
        input: { paths: filePaths }
      };
    yield "STEP";
  }

thinker.handleSteps:
function* () {
    const { agentState } = yield "STEP", lastAssistantMessage = [...agentState.messageHistory].reverse().find((m) => m.role === "assistant");
    if (!lastAssistantMessage) {
      yield {
        toolName: "set_output",
        input: { message: "Error: No assistant message found in conversation history" }
      };
      return;
    }
    const content = lastAssistantMessage.content;
    let textContent = "";
    if (typeof content === "string")
      textContent = content;
    else if (Array.isArray(content))
      textContent = content.filter((part) => part.type === "text").map((part) => part.text).join("");
    yield {
      toolName: "set_output",
      input: { message: textContent.replace(/<think>[\s\S]*?<\/think>/g, "").trim() },
      includeToolCall: !1
    };
  }

base-deep-evals.handleSteps:
function* ({ params }) {
      while (!0) {
        yield {
          toolName: "spawn_agent_inline",
          input: {
            agent_type: "context-pruner",
            params: {
              maxContextLength: 400000,
              ...params ?? {},
              cacheExpiryMs: 1800000
            }
          },
          includeToolCall: !1
        };
        const { stepsComplete } = yield "STEP";
        if (stepsComplete)
          break;
      }
    }

