librarian.handleSteps:
function* ({ prompt, params, logger }) {
    const repoUrl = params?.repoUrl;
    if (!repoUrl) {
      yield {
        toolName: "set_output",
        input: {
          message: "Error: repoUrl is required. Provide a GitHub repository URL in params."
        }
      };
      return;
    }
    const timestamp = Date.now(), cloneDir = "/tmp/librarian-" + (String(repoUrl).split("/").pop()?.replace(/\.git$/, "") || "repo") + "-" + timestamp;
