//! Live P2P transport over iroh-gossip with DHT-keyed topic discovery.
//!
//! Every device derives the same gossip [`TopicId`] from the chain fingerprint,
//! publishes its address to a distributed hash table under that topic, and
//! joins the shared gossip swarm. Two devices that hold the same recovery
//! phrase therefore find each other from anywhere on the internet — no shared
//! folder, relay config, or manual addresses needed.
//!
//! This module is native-only: iroh does not support `wasm32`, and the app
//! already gates `kal-sync` out of the web build.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::mpsc as channel;
use std::sync::{Arc, Mutex};

use distributed_topic_tracker::{
    AutoDiscoveryGossip, Config as TrackerConfig, GossipSender as TrackerSender, RecordPublisher,
    TopicId as TrackerTopicId,
};
use ed25519_dalek::SigningKey;
use iroh::endpoint::presets;
use iroh::protocol::Router;
use iroh::{Endpoint, SecretKey};
use iroh_gossip::net::Gossip;
use serde::{Deserialize, Serialize};
use ulid::Ulid;

use crate::keys::ChainIdentity;
use crate::session::{SyncError, Transport};

/// Topic wire name. Stable across devices sharing a chain because it derives
/// from the (chain-wide) fingerprint rather than any per-device value.
fn topic_name(chain: &ChainIdentity) -> String {
    format!("kal-sync/{}", chain.fingerprint().fingerprint_hex)
}

/// A frame broadcast on the gossip topic.
///
/// Wrapping the (already encrypted) blob lets recipients distinguish who sent
/// it: the gossip transport has no notion of a sender id of its own, while
/// kal's sync round skips its own re-broadcasts and names senders by ULID.
#[derive(Debug, Serialize, Deserialize)]
struct GossipFrame {
    from: String,
    blob: Vec<u8>,
}

/// Long-lived live transport for a sync chain.
///
/// Owns a tokio runtime, the iroh endpoint + router, and the gossip topic.
/// `send`/`recv` mirror the folder transport's contract: publish our state and
/// drain anything peers have written, so the caller (or a background loop)
/// drives convergence exactly like the folder path.
pub struct IrohTransport {
    /// Kept alive so the endpoint's background tasks keep running.
    _runtime: tokio::runtime::Runtime,
    endpoint: Endpoint,
    _router: Router,
    sender: TrackerSender,
    /// Gazette of messages pushed by the background receive loop. Wrapped in a
    /// `Mutex` so the transport stays [`Sync`] (a `std` mpsc `Receiver` is not).
    inbox: Mutex<channel::Receiver<(String, Vec<u8>)>>,
    /// Latest sealed state, re-broadcast to newly joined peers automatically.
    latest: Arc<Mutex<Option<Vec<u8>>>>,
    /// Neighbor count — whether the gossip topic currently has peers.
    neighbors: Arc<AtomicUsize>,
    device_id: String,
}

impl IrohTransport {
    /// A fresh random per-device iroh identity. Persist the result next to the
    /// chain identity so restarts keep the same endpoint id.
    pub fn new_node_secret() -> [u8; 32] {
        SecretKey::generate().to_bytes()
    }

    /// Connect to the chain's gossip topic using the public n0 relay + DHT
    /// discovery. Returns once the topic subscription is up; peer discovery
    /// and joining continue in the background (a lone device must not block).
    ///
    /// `node_secret` is this device's long-lived iroh identity and `device_id`
    /// its stable ULID; persist both to keep reconnects fast and revocation
    /// stable across app restarts.
    pub fn connect(
        chain: &ChainIdentity,
        device_id: Ulid,
        node_secret: [u8; 32],
    ) -> Result<Self, SyncError> {
        let runtime = tokio::runtime::Runtime::new()
            .map_err(|e| SyncError::Live(format!("tokio runtime: {e}")))?;
        let secret = SecretKey::from_bytes(&node_secret);
        let device_str = device_id.to_string();

        let (endpoint, router, sender, inbox, latest, neighbors) = runtime.block_on(async {
            let endpoint = Endpoint::builder(presets::N0)
                .secret_key(secret.clone())
                .bind()
                .await
                .map_err(|e| SyncError::Live(format!("bind endpoint: {e}")))?;

            let gossip = Gossip::builder().spawn(endpoint.clone());
            let router = Router::builder(endpoint.clone())
                .accept(iroh_gossip::ALPN, gossip.clone())
                .spawn();

            // The DHT record's signing key must match the endpoint identity:
            // bootstrap recovers peer node ids from the records' public keys.
            let signing_key = SigningKey::from_bytes(&secret.to_bytes());
            let topic = TrackerTopicId::new(topic_name(chain));
            let initial_secret = topic_name(chain).into_bytes();
            let record_publisher = RecordPublisher::new(
                topic,
                signing_key,
                None,
                initial_secret,
                TrackerConfig::default(),
            );

            let topic = gossip
                .subscribe_and_join_with_auto_discovery_no_wait(record_publisher)
                .await
                .map_err(|e| SyncError::Live(format!("join topic: {e}")))?;
            let (sender, mut receiver) = topic
                .split()
                .await
                .map_err(|e| SyncError::Live(format!("split topic: {e}")))?;

            let (tx, inbox) = channel::channel::<(String, Vec<u8>)>();
            let latest = Arc::new(Mutex::new(None::<Vec<u8>>));
            let neighbors = Arc::new(AtomicUsize::new(0));
            let latest_clone = latest.clone();
            let neighbors_clone = neighbors.clone();
            let sender_clone = sender.clone();
            tokio::spawn(async move {
                let mut last_sent = None::<Vec<u8>>;
                loop {
                    match receiver.next().await {
                        Ok(iroh_gossip::api::Event::Received(message)) => {
                            if let Ok(frame) =
                                serde_json::from_slice::<GossipFrame>(&message.content)
                            {
                                let _ = tx.send((frame.from, frame.blob));
                            }
                        }
                        Ok(iroh_gossip::api::Event::NeighborUp(_)) => {
                            neighbors_clone.fetch_add(1, Ordering::Relaxed);
                            let snapshot = latest_clone.lock().unwrap().clone();
                            if let Some(snapshot) = snapshot {
                                // Push our latest state to the fresh peer without
                                // spamming when nothing changed since last time.
                                if last_sent.as_deref() != Some(snapshot.as_slice())
                                    && sender_clone.broadcast(snapshot.clone()).await.is_ok()
                                {
                                    last_sent = Some(snapshot);
                                }
                            }
                        }
                        Ok(iroh_gossip::api::Event::NeighborDown(_)) => {
                            let _ = neighbors_clone.fetch_update(
                                Ordering::Relaxed,
                                Ordering::Relaxed,
                                |n| Some(n.saturating_sub(1)),
                            );
                        }
                        Ok(_) => {}
                        Err(_) => break,
                    }
                }
            });

            Ok::<_, SyncError>((
                endpoint,
                router,
                sender,
                Mutex::new(inbox),
                latest,
                neighbors,
            ))
        })?;

        Ok(Self {
            _runtime: runtime,
            endpoint,
            _router: router,
            sender,
            inbox,
            latest,
            neighbors,
            device_id: device_str,
        })
    }

    /// Stable device id used as the sender tag in broadcast frames.
    pub fn device_id(&self) -> &str {
        &self.device_id
    }

    /// Remember the current sealed state so it is re-broadcast to peers that
    /// join later. Call this whenever local state may have changed.
    pub fn set_state(&self, blob: Vec<u8>) {
        *self.latest.lock().unwrap() = Some(blob);
    }

    /// Whether the gossip topic currently has at least one peer connected.
    /// The app uses this to prefer the live channel over the folder transport.
    pub fn is_joined(&self) -> bool {
        self.neighbors.load(Ordering::Relaxed) > 0
    }

    /// The endpoint this transport is bound to (mostly for diagnostics/tests).
    pub fn endpoint_id(&self) -> String {
        format!("{:?}", self.endpoint.id())
    }
}

impl Transport for IrohTransport {
    fn send(&self, _addr: &str, blob: &[u8]) -> Result<(), SyncError> {
        let frame = GossipFrame {
            from: self.device_id.clone(),
            blob: blob.to_vec(),
        };
        let bytes = serde_json::to_vec(&frame)
            .map_err(|e| SyncError::Live(format!("encode frame: {e}")))?;
        self._runtime
            .block_on(self.sender.broadcast(bytes))
            .map_err(|e| SyncError::Live(format!("broadcast: {e}")))?;
        Ok(())
    }

    fn recv(&self) -> Option<(String, Vec<u8>)> {
        self.inbox
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .try_recv()
            .ok()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const PHRASE: &str =
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

    #[test]
    fn topic_name_is_stable_across_devices_and_unique_across_chains() {
        let a = ChainIdentity::from_phrase(PHRASE).unwrap();
        let b = ChainIdentity::from_phrase(PHRASE).unwrap();
        let other = ChainIdentity::generate().unwrap();
        assert_eq!(topic_name(&a), topic_name(&b));
        assert_ne!(topic_name(&a), topic_name(&other));
    }

    #[test]
    fn frame_round_trips() {
        let frame = GossipFrame {
            from: Ulid::new().to_string(),
            blob: vec![1, 2, 3, 250, 251, 252],
        };
        let bytes = serde_json::to_vec(&frame).unwrap();
        let decoded: GossipFrame = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(decoded.from, frame.from);
        assert_eq!(decoded.blob, frame.blob);
    }
}

//! Long-lived live P2P transport for the sync chain (native only).
//!
//! Owns the per-device iroh identity + a gossip-joined transport for the
//! current chain. The DHT-keyed topic makes same-phrase devices reachable from
//! anywhere, so mobile joiners pull state from desktop automatically once the
//! two gossip neighbours meet.

use std::sync::{Arc, Mutex, OnceLock};

use kal_sync::live::IrohTransport;
use kal_sync::{ChainIdentity, SyncSession, SyncState};

use crate::DbHandle;

/// One transport per device, keyed by the chain fingerprint it joined.
type LiveSlot = (String, Arc<IrohTransport>);
static LIVE: OnceLock<Mutex<Option<LiveSlot>>> = OnceLock::new();

/// The slice of a live transport that a sync round needs.
///
/// Kept as a trait (rather than reaching for `IrohTransport` directly) so the
/// orchestration in [`live_round_core`] can be unit-tested against a fake,
/// in-memory transport — the real DHT/gossip networking can't run in CI.
pub trait LiveSink {
    fn device_id(&self) -> &str;
    /// Whether the gossip topic currently has at least one peer.
    fn is_joined(&self) -> bool;
    /// Remember the latest sealed state so newly-joined peers get it pushed.
    fn set_state(&self, blob: Vec<u8>);
    /// Broadcast our sealed state to all current peers.
    fn broadcast(&self, blob: &[u8]) -> Result<(), String>;
    /// Drain any state peers have pushed to us.
    fn recv(&self) -> Option<(String, Vec<u8>)>;
}

impl LiveSink for IrohTransport {
    fn device_id(&self) -> &str {
        IrohTransport::device_id(self)
    }
    fn is_joined(&self) -> bool {
        IrohTransport::is_joined(self)
    }
    fn set_state(&self, blob: Vec<u8>) {
        IrohTransport::set_state(self, blob)
    }
    fn broadcast(&self, blob: &[u8]) -> Result<(), String> {
        // addr is unused by the gossip transport, so "" is fine.
        kal_sync::Transport::send(self, "", blob).map_err(|e| e.to_string())
    }
    fn recv(&self) -> Option<(String, Vec<u8>)> {
        kal_sync::Transport::recv(self)
    }
}

/// Per-device (not chain) identity: the iroh endpoint secret + a stable ULID.
/// Stored next to the chain identity so app restarts reuse the same endpoint
/// id (faster reconnects, stable revocation identity).
#[derive(serde::Serialize, serde::Deserialize)]
struct NodeCfg {
    node_key: String,
    device_id: String,
}

impl NodeCfg {
    fn path() -> std::path::PathBuf {
        crate::sync_ui::identity_path(&crate::default_db_path().unwrap_or_default())
            .with_file_name("sync-node.json")
    }

    fn load_or_create() -> Option<Self> {
        let path = Self::path();
        if let Ok(text) = std::fs::read_to_string(&path) {
            if let Ok(cfg) = serde_json::from_str::<NodeCfg>(&text) {
                return Some(cfg);
            }
        }
        let cfg = NodeCfg {
            // Reuse iroh's RNG via kal-sync rather than pulling a rand dependency.
            node_key: encode_hex(&IrohTransport::new_node_secret()),
            device_id: ulid::Ulid::new().to_string(),
        };
        let dir = path.parent()?;
        std::fs::create_dir_all(dir).ok()?;
        let json = serde_json::to_string(&cfg).ok()?;
        std::fs::write(&path, json).ok()?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600));
        }
        Some(cfg)
    }
}

/// The live transport for `identity`, creating it on first use. Returns `None`
/// when the chain changed or the transport could not start.
///
/// Safe to call from any thread: `IrohTransport::connect` internally calls
/// `tokio::runtime::Runtime::block_on`, which panics if invoked from within an
/// existing tokio runtime (e.g. a Dioxus render/effect thread). So whenever a
/// fresh transport must be built, it is built on a dedicated OS thread that is
/// not driving any runtime; callers here may block briefly for that build.
pub fn live_transport(identity: &ChainIdentity) -> Option<Arc<IrohTransport>> {
    let fingerprint = identity.fingerprint().fingerprint_hex.clone();
    let guard = LIVE.get_or_init(|| Mutex::new(None));
    let mut slot = guard.lock().ok()?;
    if let Some((fp, t)) = slot.as_ref() {
        if fp == &fingerprint {
            return Some(t.clone());
        }
    }
    let cfg = NodeCfg::load_or_create()?;
    let device_id = cfg.device_id.parse().ok()?;
    let node_key = decode_hex(&cfg.node_key)?;

    // Clone the data we need into a 'static closure so the builder can run on
    // its own thread. The construction is synchronous and needs the ChainIdentity
    // only to derive the topic; rebuild entries are cheap enough.
    let phrase = identity.to_owned();
    let build = std::thread::Builder::new()
        .name("kal-live-connect".into())
        .spawn(move || IrohTransport::connect(&phrase, device_id, node_key))
        .ok()?;
    let transport = build.join().ok()?.ok()?;
    *slot = Some((fingerprint, Arc::new(transport)));
    slot.as_ref().map(|(_, t)| t.clone())
}

/// Run one full live sync round. Creates the transport on first call (if not
/// already cached) and waits up to `PEER_TIMEOUT` for DHT peer discovery
/// before giving up.  Callers fall back to the folder transport when this
/// returns `Err`.
pub fn sync_round(identity: &ChainIdentity, db: &DbHandle) -> Result<usize, String> {
    let transport = live_transport(identity).ok_or("live P2P unavailable")?;
    let sink: &dyn LiveSink = &*transport;

    // The transport's DHT record + gossip join happen asynchronously.  Give
    // the network up to 15 s to discover the first peer before we bail.
    const PEER_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(15);
    const POLL: std::time::Duration = std::time::Duration::from_millis(250);
    let deadline = std::time::Instant::now() + PEER_TIMEOUT;
    while !sink.is_joined() {
        if std::time::Instant::now() >= deadline {
            break;
        }
        std::thread::sleep(POLL);
    }
    if !sink.is_joined() {
        return Err("live P2P: no peers yet — try again in a moment".into());
    }

    live_round_core(identity, db, sink)
}

/// The pure orchestration of one live sync round, factored out so it can be
/// tested against an in-memory fake transport instead of the real gossip
/// network.
///
/// Behavior contract (the "should work" spec):
///  1. Seal our current local state and remember it for the transport
///     (`set_state`) so late-joining peers receive it via the transport's
///     auto-rebroadcast.
///  2. Broadcast our full state to the topic.
///  3. Drain everything peers sent and merge it into our session; count merged
///     peer envelopes.
///  4. Self-broadcasts (our own device id) are ignored — never counted/merged.
///  5. After any merge, persist the converged calendars + items to the DB.
///  6. Returns the number of peer envelopes merged (0 means nothing changed).
pub fn live_round_core(
    identity: &ChainIdentity,
    db: &DbHandle,
    sink: &dyn LiveSink,
) -> Result<usize, String> {
    let device_id: ulid::Ulid = sink
        .device_id()
        .parse()
        .map_err(|e| format!("bad device id: {e}"))?;
    let calendars = db.list_calendars().map_err(|e| e.to_string())?;
    let items = db.list_items(true).map_err(|e| e.to_string())?;
    let mut session = SyncSession::new(
        identity,
        device_id,
        "live",
        SyncState::from_parts(calendars.clone(), items.clone()),
    );

    let sealed = session.seal_state().map_err(|e| e.to_string())?;
    sink.set_state(sealed.clone());
    sink.broadcast(&sealed).map_err(|e| e.to_string())?;

    let self_id = sink.device_id().to_string();
    let mut merged = 0usize;
    while let Some((sender, bytes)) = sink.recv() {
        if sender == self_id {
            continue;
        }
        if session.accept_blob(&bytes).is_ok() {
            merged += 1;
        }
    }
    if merged == 0 {
        return Ok(0);
    }

    for cal in session.state.calendars.values() {
        db.upsert_calendar(cal).map_err(|e| e.to_string())?;
    }
    for item in session.state.items.values() {
        db.upsert_item(item).map_err(|e| e.to_string())?;
    }
    Ok(merged)
}

fn encode_hex(bytes: &[u8; 32]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn decode_hex(s: &str) -> Option<[u8; 32]> {
    let mut out = [0u8; 32];
    let bytes = s.as_bytes();
    if bytes.len() != 64 {
        return None;
    }
    for i in 0..32 {
        out[i] = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).ok()?;
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use kal_core::models::{Calendar, CalendarItem, Color, ItemKind};
    use kal_storage::Database;
    use std::collections::{HashMap, VecDeque};
    use std::sync::Mutex as StdMutex;

    const PHRASE: &str =
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

    /// Shared gossip mailboxes keyed by recipient device id. When any sink
    /// broadcasts, the blob is delivered to every OTHER sink's inbox — the
    /// same fan-out a real gossip topic provides.
    type MailboxMap = HashMap<String, VecDeque<(String, Vec<u8>)>>;
    #[derive(Clone, Default)]
    struct Mailboxes(Arc<StdMutex<MailboxMap>>);

    impl Mailboxes {
        fn push(&self, to: &str, from: String, blob: Vec<u8>) {
            self.0
                .lock()
                .unwrap()
                .entry(to.to_string())
                .or_default()
                .push_back((from, blob));
        }
        fn pop(&self, me: &str) -> Option<(String, Vec<u8>)> {
            self.0
                .lock()
                .unwrap()
                .entry(me.to_string())
                .or_default()
                .pop_front()
        }
        fn members(&self) -> Vec<String> {
            self.0.lock().unwrap().keys().cloned().collect()
        }
    }

    /// A fake live transport with the same contract as `IrohTransport`, but
    /// fully in-memory so the sync orchestration can be exercised in CI.
    ///
    /// `me` must be a well-formed ULID (the real transport's device id always
    /// is), because `live_round_core` parses it into a `Ulid`.
    struct FakeSink {
        me: String,
        joined: bool,
        mail: Mailboxes,
        state: StdMutex<Option<Vec<u8>>>,
    }

    impl FakeSink {
        fn new(me: &str, mail: Mailboxes) -> Self {
            Self {
                me: me.to_string(),
                joined: true, // fake sinks are considered joined to keep the test focused on merge logic
                mail,
                state: StdMutex::new(None),
            }
        }
        fn ulid() -> String {
            ulid::Ulid::new().to_string()
        }
    }

    impl LiveSink for FakeSink {
        fn device_id(&self) -> &str {
            &self.me
        }
        fn is_joined(&self) -> bool {
            self.joined
        }
        fn set_state(&self, blob: Vec<u8>) {
            *self.state.lock().unwrap() = Some(blob);
        }
        fn broadcast(&self, blob: &[u8]) -> Result<(), String> {
            for peer in self.mail.members() {
                if peer != self.me {
                    self.mail.push(&peer, self.me.clone(), blob.to_vec());
                }
            }
            Ok(())
        }
        fn recv(&self) -> Option<(String, Vec<u8>)> {
            self.mail.pop(&self.me)
        }
    }

    fn sample_item(calendar_id: ulid::Ulid, title: &str, ts_secs: i64) -> CalendarItem {
        use chrono::TimeZone;
        let start = chrono::Utc
            .timestamp_opt(ts_secs, 0)
            .single()
            .unwrap()
            .fixed_offset();
        CalendarItem::new(ItemKind::Event, title, calendar_id, start)
    }

    fn cal(name: &str) -> Calendar {
        Calendar::local(name, Color("#3366cc".into()))
    }

    /// Seed one calendar + one event onto the chain and return the sealed blob
    /// a peer would broadcast. The event is attached to the seeded calendar so
    /// the in-memory DB's `items.calendar_id REFERENCES calendars(id)` FK holds.
    fn sealed_state_with(identity: &ChainIdentity, cal_name: &str, item_title: &str) -> Vec<u8> {
        let mut s = SyncState::default();
        let cal_id = ulid::Ulid::new();
        let mut calendar = cal(cal_name);
        calendar.id = cal_id; // keep map key in lockstep with the row id so the FK holds
        s.calendars.insert(cal_id, calendar);
        s.items.insert(
            ulid::Ulid::new(),
            sample_item(cal_id, item_title, 1_700_000_000),
        );
        let session = SyncSession::new(identity, ulid::Ulid::new(), "seeder", s);
        session.seal_state().unwrap()
    }

    fn empty_db() -> DbHandle {
        Arc::new(Database::open_in_memory().unwrap())
    }

    /// Phone (fresh Android install, empty DB) joins a chain that a desktop has
    /// already populated. The desktop's state is sitting in the phone's inbox
    /// (pushed via the transport's NeighborUp rebroadcast). Tapping "Sync now"
    /// must bring the desktop's calendar + event into the phone's DB.
    #[test]
    fn phone_joining_chain_pulls_desktops_state_into_its_db() {
        let identity = ChainIdentity::from_phrase(PHRASE).unwrap();
        let mail = Mailboxes::default();

        // Desktop: publishes its populated state once, which lands in the
        // phone's mailbox (and any other peer) via the transport's
        // NeighborUp-style rebroadcast.
        let desktop_id = FakeSink::ulid();
        let desktop_blob = sealed_state_with(&identity, "Work", "Standup");

        // Phone: joins with an empty DB, with the desktop's state sitting in
        // its inbox, then syncs.
        let phone_id = FakeSink::ulid();
        let phone = FakeSink::new(&phone_id, mail.clone());
        mail.push(&phone_id, desktop_id, desktop_blob);
        let db = empty_db();
        let merged = live_round_core(&identity, &db, &phone).unwrap();

        assert!(merged >= 1, "phone must merge the desktop's state");
        let cals = db.list_calendars().unwrap();
        let items = db.list_items(false).unwrap();
        assert_eq!(cals.len(), 1);
        assert_eq!(cals[0].name, "Work");
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].title, "Standup");
    }

    /// Gossip broadcasts come back to the sender; a round must never count or
    /// persist its own echo.
    #[test]
    fn self_broadcast_is_never_merged_or_counted() {
        let identity = ChainIdentity::from_phrase(PHRASE).unwrap();
        let mail = Mailboxes::default();
        let phone_id = FakeSink::ulid();
        let phone = FakeSink::new(&phone_id, mail.clone());
        let own_blob = sealed_state_with(&identity, "Me", "Mine");
        mail.push(&phone_id, phone_id.clone(), own_blob);

        let db = empty_db();
        let merged = live_round_core(&identity, &db, &phone).unwrap();
        assert_eq!(merged, 0, "self-broadcast must not count as a merge");
        assert_eq!(db.list_items(false).unwrap().len(), 0);
        assert_eq!(db.list_calendars().unwrap().len(), 0);
    }

    /// Merging from two independent peers unions both — a phone receiving
    /// different events from two desktops keeps both.
    #[test]
    fn merges_from_multiple_peers_are_unioned() {
        let identity = ChainIdentity::from_phrase(PHRASE).unwrap();
        let mail = Mailboxes::default();

        let a_blob = sealed_state_with(&identity, "CalA", "A-event");
        let b_blob = sealed_state_with(&identity, "CalB", "B-event");

        let phone_id = FakeSink::ulid();
        let phone = FakeSink::new(&phone_id, mail.clone());
        mail.push(&phone_id, FakeSink::ulid(), a_blob);
        mail.push(&phone_id, FakeSink::ulid(), b_blob);

        let db = empty_db();
        let merged = live_round_core(&identity, &db, &phone).unwrap();
        assert_eq!(merged, 2, "both peers' envelopes are merged");
        let cals = db.list_calendars().unwrap();
        let items = db.list_items(false).unwrap();
        let titles: std::collections::HashSet<String> =
            items.iter().map(|i| i.title.clone()).collect();
        assert!(titles.contains("A-event"));
        assert!(titles.contains("B-event"));
        let cal_names: std::collections::HashSet<String> =
            cals.iter().map(|c| c.name.clone()).collect();
        assert!(cal_names.contains("CalA"));
        assert!(cal_names.contains("CalB"));
    }

    /// A fresh identity has no data, so an empty chain round is a clean
    /// no-op — the phone DB stays empty but the round must not error/panic.
    #[test]
    fn empty_chain_round_is_a_clean_noop() {
        let identity = ChainIdentity::from_phrase(PHRASE).unwrap();
        let mail = Mailboxes::default();
        let phone = FakeSink::new(&FakeSink::ulid(), mail);
        let db = empty_db();
        let merged = live_round_core(&identity, &db, &phone).unwrap();
        assert_eq!(merged, 0);
        assert_eq!(db.list_items(false).unwrap().len(), 0);
    }

    /// The node-secret hex codec that keys the per-device transport must be a
    /// lossless 32-byte / 64-char round trip (corrupting it would make a phone
    /// unable to reconnect to its own DHT identity across restarts).
    #[test]
    fn node_secret_hex_round_trips_and_chains_differ() {
        let key = IrohTransport::new_node_secret();
        let hex = encode_hex(&key);
        assert_eq!(hex.len(), 64);
        assert_eq!(decode_hex(&hex), Some(key));
        // Distinct chains must never collide on the same topic fingerprint.
        let a = ChainIdentity::from_phrase(PHRASE).unwrap();
        let b = ChainIdentity::generate().unwrap();
        assert_ne!(
            a.fingerprint().fingerprint_hex,
            b.fingerprint().fingerprint_hex
        );
        // The same phrase always resolves to the same fingerprint on any device.
        let a2 = ChainIdentity::from_phrase(PHRASE).unwrap();
        assert_eq!(
            a.fingerprint().fingerprint_hex,
            a2.fingerprint().fingerprint_hex
        );
    }
}

//! Bootstrap process for discovering and joining peers via DHT.

use std::collections::HashSet;

use actor_helper::{Handle, act, act_ok};
use anyhow::Result;
use iroh::EndpointId;
use tokio::time::sleep;
use tokio_util::sync::CancellationToken;

use crate::{
    GossipSender, MAX_MESSAGE_HASHES, MAX_RECORD_PEERS, RecordPublisher, TimeoutConfig, config::BootstrapConfig, crypto::Record, gossip::{GossipRecordContent, receiver::GossipReceiver}
};

/// Manages the peer discovery and joining process.
///
/// Queries DHT for bootstrap records, extracts node IDs, and progressively
/// joins peers until the local node is connected to the topic.
#[derive(Debug, Clone)]
pub struct Bootstrap {
    api: Handle<BootstrapActor, anyhow::Error>,
}

#[derive(Debug)]
struct BootstrapActor {
    record_publisher: RecordPublisher,
    gossip_sender: GossipSender,
    gossip_receiver: GossipReceiver,
    cancel_token: tokio_util::sync::CancellationToken,
    config: BootstrapConfig,
}

impl Bootstrap {
    /// Create a new bootstrap process for a topic.
    pub async fn new(
        record_publisher: RecordPublisher,
        gossip: iroh_gossip::net::Gossip,
        cancel_token: tokio_util::sync::CancellationToken,
        timeout_config: TimeoutConfig,
        bootstrap_config: BootstrapConfig,
    ) -> Result<Self> {
        let gossip_topic: iroh_gossip::api::GossipTopic = gossip
            .subscribe(
                iroh_gossip::proto::TopicId::from(record_publisher.topic_id().hash()),
                vec![],
            )
            .await?;
        let (gossip_sender, gossip_receiver) = gossip_topic.split();
        let (gossip_sender, gossip_receiver) = (
            GossipSender::new(gossip_sender, timeout_config),
            GossipReceiver::new(gossip_receiver, cancel_token.clone()),
        );

        let api = Handle::spawn(BootstrapActor {
            record_publisher,
            gossip_sender,
            gossip_receiver,
            cancel_token,
            config: bootstrap_config,
        })
        .0;

        Ok(Self { api })
    }

    /// Start the bootstrap process.
    ///
    /// Returns a receiver that signals completion when the node has joined the topic (has at least one neighbor).
    pub async fn bootstrap(&self) -> Result<tokio::sync::oneshot::Receiver<Result<()>>> {
        self.api.call(act!(actor=> actor.start_bootstrap())).await
    }

    /// Get the gossip sender for this topic.
    pub async fn gossip_sender(&self) -> Result<GossipSender> {
        self.api
            .call(act_ok!(actor => async move { actor.gossip_sender.clone() }))
            .await
    }

    /// Get the gossip receiver for this topic.
    pub async fn gossip_receiver(&self) -> Result<GossipReceiver> {
        self.api
            .call(act_ok!(actor => async move { actor.gossip_receiver.clone() }))
            .await
    }
}

impl BootstrapActor {
    pub async fn start_bootstrap(&mut self) -> Result<tokio::sync::oneshot::Receiver<Result<()>>> {
        let (sender, receiver) = tokio::sync::oneshot::channel();
        tokio::spawn({
            let mut last_published_unix_minute = 0;
            let (gossip_sender, mut gossip_receiver) =
                (self.gossip_sender.clone(), self.gossip_receiver.clone());
            let record_publisher = self.record_publisher.clone();
            let cancel_token = self.cancel_token.clone();
            let bootstrap_config = self.config.clone();
            let mut is_joined_ret = false;

            if self.config.publish_record_on_startup() {
                let unix_minute = crate::unix_minute(0);
                tracing::debug!("Bootstrap: initial startup record publish {}", unix_minute);
                last_published_unix_minute = if self.config.check_older_records_first_on_startup() {
                    0
                } else {
                    unix_minute
                };
                let record_creator = record_publisher.clone();
                let record_content = GossipRecordContent {
                    active_peers: [[0; 32]; MAX_RECORD_PEERS],
                    last_message_hashes: [[0; 32]; MAX_MESSAGE_HASHES],
                };
                if let Ok(record) = Record::sign(
                    record_publisher.topic_id().hash(),
                    unix_minute,
                    record_content,
                    record_publisher.signing_key(),
                ) {
                    publish_record_fire_and_forget(
                        record_creator,
                        record,
                        None,
                        cancel_token.clone(),
                    );
                }
            }

            async move {
                tracing::debug!("Bootstrap: starting bootstrap process");
                'bootstrap: while !cancel_token.is_cancelled() {
                    // Check if we are connected to at least one node
                    let is_joined = gossip_receiver.is_joined().await;
                    if let Ok(is_joined) = is_joined
                        && is_joined
                    {
                        tracing::debug!("Bootstrap: already joined, exiting bootstrap loop");
                        is_joined_ret = true;
                        break;
                    } else if let Err(e) = is_joined {
                        tracing::debug!("Bootstrap: error checking join status: {:?}", e);
                        break;
                    }

                    let current_unix_minute = crate::unix_minute(0);

                    let mut use_cached_next = true;
                    // last_published_unix_minute == 0 means first run
                    let unix_minute_offset = if last_published_unix_minute == 0
                        && bootstrap_config.check_older_records_first_on_startup()
                    {
                        use_cached_next = false;
                        1
                    } else {
                        0
                    };

                    // Unique, verified records for the unix minute
                    let mut records = record_publisher
                        .get_records(
                            current_unix_minute.saturating_sub(unix_minute_offset + 1),
                            cancel_token.clone(),
                        )
                        .await
                        .unwrap_or_default();
                    let current_records = record_publisher
                        .get_records(
                            current_unix_minute.saturating_sub(unix_minute_offset),
                            cancel_token.clone(),
                        )
                        .await
                        .unwrap_or_default();
                    records.extend(current_records.clone());

                    tracing::debug!(
                        "Bootstrap: fetched {} records for unix_minute {}",
                        records.len(),
                        current_unix_minute
                    );

                    // If there are no records, invoke the publish_proc (the publishing procedure)
                    // continue the loop after
                    if records.is_empty() {
                        if current_unix_minute != last_published_unix_minute {
                            tracing::debug!(
                                "Bootstrap: no records found, publishing own record for unix_minute {}",
                                current_unix_minute
                            );
                            last_published_unix_minute = current_unix_minute;
                            let record_creator = record_publisher.clone();
                            let record_content = GossipRecordContent {
                                active_peers: [[0; 32]; MAX_RECORD_PEERS],
                                last_message_hashes: [[0; 32]; MAX_MESSAGE_HASHES],
                            };
                            if let Ok(record) = Record::sign(
                                record_publisher.topic_id().hash(),
                                current_unix_minute,
                                record_content,
                                record_publisher.signing_key(),
                            ) {
                                publish_record_fire_and_forget(
                                    record_creator,
                                    record,
                                    if use_cached_next {
                                        Some(current_records.clone())
                                    } else {
                                        None
                                    },
                                    cancel_token.clone(),
                                );
                            }
                        }
                        tokio::select! {
                            _ = sleep(bootstrap_config.no_peers_retry_interval()) => {}
                            _ = gossip_receiver.joined() => continue,
                            _ = cancel_token.cancelled() => break,
                        }
                        continue;
                    }

                    // We found records

                    // Collect node ids from active_peers and record.pub_key (of publisher)
                    let bootstrap_nodes = records
                        .iter()
                        .flat_map(|record| {
                            // records are already filtered by self entry
                            let mut v = vec![record.pub_key()];

                            if let Ok(record_content) = record.content::<GossipRecordContent>() {
                                for peer in record_content.active_peers {
                                    if peer != [0; 32]
                                        && !peer.eq(record_publisher.pub_key().as_bytes())
                                    {
                                        v.push(peer);
                                    }
                                }
                            }
                            v
                        })
                        .filter_map(|pub_key| EndpointId::from_bytes(&pub_key).ok())
                        .collect::<HashSet<_>>();

                    tracing::debug!(
                        "Bootstrap: extracted {} potential bootstrap nodes",
                        bootstrap_nodes.len()
                    );

                    // Maybe in the meantime someone connected to us via one of our published records
                    // we don't want to disrup the gossip rotations any more then we have to
                    // so we check again before joining new peers
                    let is_joined = gossip_receiver.is_joined().await;
                    if let Ok(is_joined) = is_joined
                        && is_joined
                    {
                        tracing::debug!("Bootstrap: joined while processing records, exiting");
                        is_joined_ret = true;
                        break;
                    } else if let Err(e) = is_joined {
                        tracing::debug!("Bootstrap: error checking join status: {:?}", e);
                        break;
                    }

                    // Instead of throwing everything into join_peers() at once we go pub_key by pub_key
                    // again to disrupt as little nodes peer neighborhoods as possible.
                    for pub_key in bootstrap_nodes.iter() {
                        match gossip_sender.join_peers(vec![*pub_key], None).await {
                            Ok(_) => {
                                tracing::debug!("Bootstrap: attempted to join peer {}", pub_key);

                                tokio::select! {
                                    _ = sleep(bootstrap_config.per_peer_join_settle_time()) => {}
                                    _ = gossip_receiver.joined() => {},
                                    _ = cancel_token.cancelled() => break 'bootstrap,
                                }
                                let is_joined = gossip_receiver.is_joined().await;
                                if let Ok(is_joined) = is_joined
                                    && is_joined
                                {
                                    tracing::debug!(
                                        "Bootstrap: successfully joined via peer {}",
                                        pub_key
                                    );
                                    is_joined_ret = true;
                                    break;
                                } else if let Err(e) = is_joined {
                                    tracing::debug!(
                                        "Bootstrap: error checking join status: {:?}",
                                        e
                                    );
                                    break;
                                }
                            }
                            Err(e) => {
                                tracing::debug!(
                                    "Bootstrap: failed to join peer {}: {:?}",
                                    pub_key,
                                    e
                                );
                                continue;
                            }
                        }
                    }

                    // If we are still not connected to anyone:
                    // give it the default iroh-gossip connection timeout before the final is_joined() check
                    let is_joined = gossip_receiver.is_joined().await;
                    if let Ok(is_joined) = is_joined
                        && !is_joined
                    {
                        tracing::debug!(
                            "Bootstrap: not joined yet, waiting {:?} before final check",
                            bootstrap_config.join_confirmation_wait_time()
                        );
                        tokio::select! {
                            _ = sleep(bootstrap_config.join_confirmation_wait_time()) => {}
                            _ = gossip_receiver.joined() => {},
                            _ = cancel_token.cancelled() => break,
                        }
                    } else if let Err(e) = is_joined {
                        tracing::debug!("Bootstrap: error checking join status: {:?}", e);
                        break;
                    }

                    // If we are connected: return
                    let is_joined = gossip_receiver.is_joined().await;
                    if let Ok(is_joined) = is_joined
                        && is_joined
                    {
                        tracing::debug!("Bootstrap: successfully joined after final wait");
                        is_joined_ret = true;
                        break;
                    } else if let Err(e) = is_joined {
                        tracing::debug!("Bootstrap: error checking join status: {:?}", e);
                        break;
                    } else {
                        tracing::debug!("Bootstrap: still not joined after attempting all peers");
                        // If we are not connected: check if we should publish a record this minute
                        if current_unix_minute != last_published_unix_minute {
                            tracing::debug!(
                                "Bootstrap: publishing fallback record for unix_minute {}",
                                current_unix_minute
                            );
                            last_published_unix_minute = current_unix_minute;
                            let record_creator = record_publisher.clone();
                            if let Ok(record) = Record::sign(
                                record_publisher.topic_id().hash(),
                                current_unix_minute,
                                GossipRecordContent {
                                    active_peers: [[0; 32]; MAX_RECORD_PEERS],
                                    last_message_hashes: [[0; 32]; MAX_MESSAGE_HASHES],
                                },
                                record_publisher.signing_key(),
                            ) {
                                publish_record_fire_and_forget(
                                    record_creator,
                                    record,
                                    if use_cached_next {
                                        Some(current_records)
                                    } else {
                                        None
                                    },
                                    cancel_token.clone(),
                                );
                            }
                        }
                        tokio::select! {
                            _ = sleep(bootstrap_config.discovery_poll_interval()) => continue,
                            _ = gossip_receiver.joined() => continue,
                            _ = cancel_token.cancelled() => break,
                        }
                    }
                }
                tracing::debug!("Bootstrap: exited");

                if is_joined_ret {
                    let _ = sender.send(Ok(()));
                } else {
                    let _ = sender.send(Err(anyhow::anyhow!(
                        "Bootstrap process failed or was cancelled"
                    )));
                }
            }
        });

        Ok(receiver)
    }
}

fn publish_record_fire_and_forget(
    record_publisher: RecordPublisher,
    record: Record,
    cached_records: Option<HashSet<Record>>,
    cancel_token: CancellationToken,
) {
    tokio::spawn(async move {
        if let Err(err) = record_publisher
            .publish_record_cached_records(record, cached_records, cancel_token)
            .await
        {
            tracing::warn!("Failed to publish record: {:?}", err);
        }
    });
}

//! Topic management: bootstrap, publishing, and peer merging.

mod bootstrap;
mod publisher;
#[allow(clippy::module_inception)]
mod topic;

pub use bootstrap::Bootstrap;
