    /// Default: 10s.
    pub fn get_timeout(mut self, timeout: Duration) -> Self {
        if timeout > Duration::ZERO {
            self.config.get_timeout = timeout;
        }
        self
    }

    /// Build the `DhtConfig`.
    pub fn build(self) -> DhtConfig {
        self.config
    }
}

