    let a = thread::spawn(move || IrohTransport::connect(&identity, a_id, IrohTransport::new_node_secret()));
    let b = thread::spawn(|| IrohTransport::connect(&identity, b_id, IrohTransport::new_node_secret()));

    let a = a.join().unwrap()?;
    let b = b.join().unwrap()?;
    println!("A endpoint: {}", a.endpoint_id());
    println!("B endpoint: {}", b.endpoint_id());

    let deadline = Instant::now() + Duration::from_secs(180);
