//! Startup tracing: write a DEBUG-level trace to a rotating file in the app
//! data dir (or stderr on desktop) so the iroh/gossip bootstrap path is
//! inspectable (adb run-as com.kal.calendar pull ...).
use std::io::Write;
use std::path::PathBuf;

pub fn init_trace_log() {
    // Best-effort; never fail the app on logging setup.
    let path = trace_path();
    let file = match std::fs::File::create(&path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let _ = tracing_subscriber::fmt()
        .with_max_level(tracing::Level::DEBUG)
        .with_ansi(false)
        .with_writer(file)
        .with_target(true)
        .with_thread_names(true)
        .try_init();
}

fn trace_path() -> PathBuf {
    crate::app_data_dir().map(|d| d.join("kal").join("sync-trace.log")).unwrap_or_else(|| PathBuf::from("sync-trace.log"))
